/** The app's continueHint (src/agentChoices.ts). */
function continueHint(agent: AgentId): string {
  const { resume } = START[agent];
  if (resume === "directory") return "Continue the most recent conversation in this folder instead of starting a new one";
  if (resume === "account") return `Continue the most recent ${agentLabel(agent)} conversation on this account, from any folder`;
  return `Continue the most recent ${agentLabel(agent)} conversation, which may come from another folder`;
}

const FOLDERS = ["~/fieldnotes/api", "~/fieldnotes/web", "~/fieldnotes/docs"];
// The quick folders under the form: the active tile's folder (api), then
// this device's recent session folders, at most three.
const SHORTCUTS = [
  { path: FOLDERS[0], label: "This tile's folder" },
  { path: FOLDERS[1], label: "web" },
  { path: FOLDERS[2], label: "docs" },
];

/* The loop: sessions the form starts in turn, every agent one that takes a
   first prompt. The first is the page's own frame; each round walks the list
   from one to the next, picks it and types its name and prompt. The prompts
   fit the prompt field's one line, as short first prompts do. */
const DEMO: { agent: AgentId; name: string; prompt: string }[] = [
  { agent: "codex", name: "tags", prompt: "Link each tag to the notes that use it" },
  { agent: "gemini", name: "pinned", prompt: "Let a note be pinned to the top of the list" },
  { agent: "claude", name: "export", prompt: "Add a Markdown export to the note page" },
  { agent: "cursor", name: "drafts", prompt: "Autosave the note editor as a draft" },
];
// Holds: the open list, each arrow step, the highlight before Enter, the closed form, the cleared fields, the typed session.
const HOLD_OPEN_MS = 1500;
const STEP_MS = 300;
const BEFORE_PICK_MS = 550;
const AFTER_PICK_MS = 700;
const CLEARED_MS = 450;
const HOLD_TYPED_MS = 2600;
const NAME_KEY_MS = 60;
const PROMPT_KEY_MS = 30;
const BETWEEN_FIELDS_MS = 250;

/* ------------------------------------------------------- agent search -- */

// The app's Select ranking (src/ui/selectSearch.ts): every query word must
// match the label, a keyword (maker, command) or the id; a label hit sorts first.
const fold = (text: string) => text.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
const words = (text: string, humps: boolean) =>
  (humps ? text.replace(/([a-z0-9])([A-Z])/g, "$1 $2") : text).split(/[^\p{L}\p{N}]+/u).map(fold).filter(Boolean);

interface Field {
  full: string;
  compact: string;
  words: string[];
  initials: string[];
}

function field(text: string): Field {
  const split = words(text, true);
  const plain = words(text, false);
  return {
    full: fold(text),
    compact: plain.join(""),
    words: [...new Set([...split, ...plain])],
    initials: [...new Set([split.map((word) => word[0]).join(""), plain.map((word) => word[0]).join("")])],
  };
}

const isSubsequence = (needle: string, haystack: string) => {
  let at = 0;
  for (const char of haystack) if (char === needle[at]) at += 1;
  return at === needle.length;
};

function tokenScore(token: string, target: Field, loose: boolean): number {
  if (target.full === token || target.compact === token) return 100;
  if (target.full.startsWith(token) || target.compact.startsWith(token)) return 90;
  if (target.words.some((word) => word.startsWith(token))) return 80;
  if (token.length >= 2 && target.initials.some((initials) => initials.startsWith(token))) return 75;
  if (target.full.includes(token) || target.compact.includes(token)) return 60;
  if (loose && token.length >= 3 && isSubsequence(token, target.compact)) return 30;
  return 0;
}

interface AgentOption {
  value: Agent;
  label: string;
  group?: "Agents" | "More agents";
  keywords: string[];
}

function scoreOption(option: AgentOption, query: string): number {
  const tokens = words(query, false);
  if (tokens.length === 0) return 1;
  const fields = [
    { target: field(option.label), penalty: 0, loose: true },
    ...option.keywords.map((keyword) => ({ target: field(keyword), penalty: 5, loose: true })),
    { target: field(option.value === "terminal" ? "" : option.value), penalty: 5, loose: false },
  ];
  let total = 0;
  for (const token of tokens) {
    let best = 0;
    for (const { target, penalty, loose } of fields) {
      const score = tokenScore(token, target, loose);
      if (score > 0) best = Math.max(best, score - penalty);
    }
    if (best <= 0) return 0;
    total += best;
  }
  return total;
}

// Terminal, then the catalog by tier (agentSelectOptions), as the list shows them.
const OPTIONS: AgentOption[] = [
  { value: "terminal", label: "Terminal", keywords: [] },
  ...[...AGENTS]
    .sort((a, b) => a.tier - b.tier)
    .map((a): AgentOption => ({ value: a.id, label: a.label, group: a.tier === 1 ? "Agents" : "More agents", keywords: [a.vendor, START[a.id].command, a.id] })),
];
// The unfiltered list in row order, for the arrow keys.
const ROW_ORDER = OPTIONS.map((option) => option.value);

/** The list's sections for a query: ranked rows, grouped in the order the groups first appear. */
function useSections(query: string) {
  return useMemo(() => {
    const ranked = words(query, false).length
      ? OPTIONS.map((option, index) => ({ option, index, score: scoreOption(option, query) }))
          .filter((entry) => entry.score > 0)
          .sort((a, b) => b.score - a.score || a.index - b.index)
          .map((entry) => entry.option)
      : OPTIONS;
    const groups = [...new Set(OPTIONS.map((option) => option.group))];
    return groups.map((group) => ({ group, rows: ranked.filter((option) => option.group === group) })).filter((section) => section.rows.length > 0);
  }, [query]);
}

/* ------------------------------------------------------------ helpers -- */

/** The app's useAutoGrow: the textarea grows with its text, up to `maxLines`. */
function useAutoGrow(ref: RefObject<HTMLTextAreaElement>, value: string, maxLines: number) {
  useLayoutEffect(() => {
    const element = ref.current;
    if (!element) return;
    const style = getComputedStyle(element);
    const line = parseFloat(style.lineHeight) || parseFloat(style.fontSize) * 1.45 || 18;
    const chrome = parseFloat(style.paddingTop) + parseFloat(style.paddingBottom) + parseFloat(style.borderTopWidth) + parseFloat(style.borderBottomWidth);
    const min = line + chrome;
    const max = line * maxLines + chrome;
    element.style.height = "auto";
    const height = value ? Math.min(Math.max(element.scrollHeight, min), max) : min;
    element.style.height = `${Math.ceil(height)}px`;
    element.style.overflowY = element.scrollHeight > max + 1 ? "auto" : "hidden";
  }, [ref, value, maxLines]);
}

/** A Select's trigger (src/ui/Select.tsx), closed unless `open`. */
function SelectButton({
  icon,
  label,
  ariaLabel,
  className = "",
  title,
  open = false,
  buttonRef,
  onClick,
}: {
  icon: ReactNode;
  label: string;
  ariaLabel: string;
  className?: string;
  title?: string;
  open?: boolean;
  buttonRef?: RefObject<HTMLButtonElement>;
  onClick?: () => void;
}) {
  return (
    <button
      ref={buttonRef}
      type="button"
      className={`cselect ${open ? "cselect-open" : ""} ${className}`}
      aria-label={ariaLabel}
      aria-haspopup="listbox"
      aria-expanded={open}
      title={title}
      // The scene's own dismiss must not see the press that toggles the list.
      onPointerDown={onClick ? (e) => e.stopPropagation() : undefined}
      onClick={onClick}
    >
      {icon}
      <span className="cselect-value">{label}</span>
      <ChevronDown size={14} className={`muted-icon ${open ? "flip" : ""}`} />
    </button>
  );
}

const agentIcon = (id: Agent) => (id === "terminal" ? <SquareTerminal size={13} /> : <AgentMark agent={id} size={13} />);

/* -------------------------------------------------------------- panel -- */

export function NewSessionPanel({ right, top, initialMenu = false }: { right: number; top: number; initialMenu?: boolean }) {
  const [agent, setAgent] = useState<Agent>(DEMO[0].agent);
  const [menu, setMenu] = useState(initialMenu);
  const [query, setQuery] = useState("");
  const [folder, setFolder] = useState(FOLDERS[1]);
  const [resume, setResume] = useState(false);
  const [worktree, setWorktree] = useState(true);
  const [name, setName] = useState(DEMO[0].name);
  const [prompt, setPrompt] = useState(DEMO[0].prompt);
  // The list's highlighted row (the app's active row) and whether the keys
  // drive it; the loop walks it with the arrow keys.
  const [active, setActive] = useState<Agent | null>(null);
  const [keys, setKeys] = useState(false);
  // Whether the loop is typing into the composer (the app shows its focus ring).
  const [typing, setTyping] = useState(false);
  // Where the open list sits: under the Agent select, 5px below it (Select's GAP).
  const [place, setPlace] = useState<{ left: number; top: number; minWidth: number } | null>(null);
  // The list's room below its trigger (Select's --cselect-room), when the card limits it.
  const [room, setRoom] = useState<number | null>(null);
  const listId = useId();
  const menuRef = useRef<HTMLDivElement>(null);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const promptRef = useRef<HTMLTextAreaElement>(null);
  const round = useRef(0);
  // The fields the loop is typing, finished at once if it stops halfway.
  const typed = useRef<{ name: string; prompt: string } | null>(null);
  const closeMenu = useCallback(() => {
    setMenu(false);
    setQuery("");
    setActive(null);
    setKeys(false);
  }, []);
  useDismiss(menu, menuRef, closeMenu);
  const handedOver = useVisitorTakeover(root);
  useAutoGrow(promptRef, prompt, 4);

  useScenePlayback(
    root,
    async (wait: Wait) => {
      const from = DEMO[round.current % DEMO.length];
      const to = DEMO[(round.current + 1) % DEMO.length];
      // The list opens with the current agent highlighted, like the app's Select.
      setKeys(true);
      setActive(from.agent);
      await wait(HOLD_OPEN_MS);
      const target = ROW_ORDER.indexOf(to.agent);
      for (let at = ROW_ORDER.indexOf(from.agent); at !== target; ) {
        at += at < target ? 1 : -1;
        setActive(ROW_ORDER[at]);
        await wait(at === target ? BEFORE_PICK_MS : STEP_MS);
      }
      // Enter picks the highlighted agent and closes the list.
      setAgent(to.agent);
      closeMenu();
      await wait(AFTER_PICK_MS);
      // A fresh session for it: name, then its first prompt.
      typed.current = to;
      setTyping(true);
      setName("");
      setPrompt("");
      await wait(CLEARED_MS);
      for (let i = 1; i <= to.name.length; i += 1) {
        setName(to.name.slice(0, i));
        await wait(NAME_KEY_MS);
      }
      await wait(BETWEEN_FIELDS_MS);
      for (let i = 1; i <= to.prompt.length; i += 1) {
        setPrompt(to.prompt.slice(0, i));
        await wait(PROMPT_KEY_MS);
      }
      typed.current = null;
      setTyping(false);
      await wait(HOLD_TYPED_MS);
      // The agent button opens the list again for the next round.
      round.current += 1;
      setMenu(true);
    },
    {
      stopped: !initialMenu || handedOver,
      onStop: () => {
        setActive(null);
        setKeys(false);
        setTyping(false);
        if (typed.current) {
          setName(typed.current.name);
          setPrompt(typed.current.prompt);
          typed.current = null;
        }
      },
    },
  );

  // The list opens at the Agent select's bottom-left corner, as Select does
  // from the trigger's rect, measured once the form has its height.
  useLayoutEffect(() => {
    const panel = root.current;
    const button = trigger.current;
    if (!menu || !panel || !button) return;
    let left = panel.clientLeft;
    let y = panel.clientTop;
    for (let element: HTMLElement | null = button; element && element !== panel; element = element.offsetParent as HTMLElement | null) {
      left += element.offsetLeft;
      y += element.offsetTop;
    }
    const next = { left, top: y + button.offsetHeight + 5, minWidth: Math.max(button.offsetWidth, 220) };
    setPlace((previous) => (previous && previous.left === next.left && previous.top === next.top && previous.minWidth === next.minWidth ? previous : next));
  }, [menu, agent, prompt]);

  const sections = useSections(query);
  const start = agent === "terminal" ? null : START[agent];
  const takesPrompt = !!start?.prompt;
  const continueBlocked = !!start?.promptCommand && prompt.trim().length > 0;
  const bypass = start?.approval === "bypass";
  const highlighted = active ?? agent;

  // Select keeps an open list inside the room below its trigger
  // (--cselect-room, at most 300px); in a scene the room ends 8px (Select's
  // EDGE) above the card's edge, where the visible window ends. The list
  // then stops right after its last whole row, so no row is cut by the edge.
  // Not after its bottom padding: while it scrolls, the next row would show
  // through that padding.
  useLayoutEffect(() => {
    const element = menuRef.current;
    const list = element?.querySelector<HTMLElement>(".cselect-list");
    const scene = element?.closest<HTMLElement>(".pz");
    if (!element || !list || !scene) return;
    const box = scene.getBoundingClientRect();
    const scale = box.height / scene.offsetHeight || 1;
    const top = element.getBoundingClientRect().top;
    const listTop = (list.getBoundingClientRect().top - top) / scale;
    const limit = Math.min(300, (box.bottom - top) / scale - 8);
    const border = element.offsetHeight - element.clientHeight;
    let next: number | null = null;
    if (listTop + list.scrollHeight + border > limit) {
      const listBox = list.getBoundingClientRect();
      const fit = [...list.querySelectorAll<HTMLElement>(".cselect-item")]
        .map((item) => (item.getBoundingClientRect().bottom - listBox.top) / scale + list.scrollTop)
        .filter((bottom) => listTop + bottom + border <= limit);
      next = Math.round(listTop + (fit.length ? Math.max(...fit) : 0) + border);
    }
    setRoom((previous) => (previous === next ? previous : next));
  }, [place, sections]);

  // The highlighted row stays in view, as Select's reveal keeps it.
  useLayoutEffect(() => {
    const list = menuRef.current?.querySelector<HTMLElement>(".cselect-list");
    const item = list?.querySelector<HTMLElement>(".cselect-item-active");
    const scene = list?.closest<HTMLElement>(".pz");
    if (!list || !item || !scene) return;
    const scale = scene.getBoundingClientRect().height / scene.offsetHeight || 1;
    const listBox = list.getBoundingClientRect();
    const itemBox = item.getBoundingClientRect();
    const header = item.closest('[role="group"]')?.querySelector<HTMLElement>(".cselect-group-label")?.offsetHeight ?? 0;
    if (itemBox.bottom > listBox.bottom) list.scrollTop += (itemBox.bottom - listBox.bottom) / scale;
    else if (itemBox.top < listBox.top + header * scale) list.scrollTop -= (listBox.top + header * scale - itemBox.top) / scale;
  }, [highlighted, room]);

  const choose = (id: Agent) => {
    setAgent(id);
    // An agent without a starting prompt drops the typed one, and one that
    // cannot continue drops Continue, like the app.
    if (id === "terminal" || !START[id].prompt) setPrompt("");
    if (id === "terminal" || !START[id].resume) setResume(false);
    closeMenu();
  };
  const row = (option: AgentOption) => (
    <div
      key={option.value}
      role="option"
      aria-selected={option.value === agent}
      className={`cselect-item ${option.value === agent ? "cselect-item-on" : ""} ${option.value === highlighted ? "cselect-item-active" : ""}`}
      onMouseMove={() => {
        setKeys(false);
        setActive(option.value);
      }}
      onClick={() => choose(option.value)}
    >
      {agentIcon(option.value)}
      <span className="cselect-item-main">
        <span className="cselect-item-label">{option.label}</span>
      </span>
      <span className="cselect-item-check">{option.value === agent ? <Check size={14} /> : null}</span>
    </div>
  );
  const Mode = start ? modeIcon(start) : ShieldCheck;

  return (
    <>
      <div ref={root} className="menu menu-panel creation-panel" style={{ right, top, left: "auto", width: 380 }}>
        <div className="menu-body new-session-form">
          {/* Command bar: one composer box for the name and, with an agent, its first prompt. */}
          <div className={`ns-composer ${takesPrompt ? "has-prompt" : ""} ${typing ? "pz-typing" : ""}`}>
            <div className="ns-composer-line">
              <SquareTerminal size={16} className="muted-icon" />
              <input
                className="ns-input"
                aria-label="New session name"
                maxLength={120}
                placeholder="Name your session…"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
              <button type="button" className="btn btn-accent ns-create" disabled={!name.trim()}>
                Create
                <CornerDownLeft size={12} strokeWidth={2.2} />
              </button>
            </div>
            {takesPrompt ? (
              <textarea
                ref={promptRef}
                className="ns-prompt"
                rows={1}
                aria-label="Starting prompt"
                placeholder={`First prompt for ${agentLabel(agent)} (optional)…`}
                value={prompt}
                onChange={(e) => setPrompt(e.target.value.replace(/[\r\n]+/g, " "))}
              />
            ) : null}
          </div>

          {/* Where and what: device, folder, agent and, with two workspaces, the workspace. */}
          <div className="ns-seg ns-seg-grid" role="group" aria-label="Session device, folder, agent and workspace">
            <SelectButton icon={<DeviceIcon />} label="This Device" ariaLabel="Session device" className="ns-pill" />
            <span className={`ns-pill-path ${folder ? "has-value" : ""}`}>
              <button type="button" className={`path-field ${folder ? "" : "path-field-empty"} ns-pill`} title={folder || "Choose a folder"}>
                <FolderOpen size={13} className="path-field-icon" />
                <span className="path-field-value">{folder || "Home folder"}</span>
              </button>
              {folder ? (
                <button type="button" className="ns-clear" title="Use the home folder" aria-label="Use the home folder" onClick={() => setFolder("")}>
                  <X size={11} />
                </button>
              ) : null}
            </span>
            <SelectButton
              buttonRef={trigger}
              icon={agentIcon(agent)}
              label={agentLabel(agent)}
              ariaLabel="Agent to start"
              className="ns-pill"
              open={menu}
              onClick={() => (menu ? closeMenu() : setMenu(true))}
            />
            <SelectButton icon={<LayoutGrid size={13} />} label="fieldnotes" ariaLabel="Session workspace" className="ns-pill" />
          </div>

          {/* Options that apply only sometimes: the agent's mode, continuing its
              last conversation and a worktree. */}
          {start || folder ? (
            <div className="ns-seg ns-seg-extra" role="group" aria-label="Session options">
              {start && start.modes > 1 ? (
                <SelectButton
                  icon={createElement(Mode, { size: 13 })}
                  label={start.mode}
                  ariaLabel={`${agentLabel(agent)} mode`}
                  className={`ns-pill ns-mode ${bypass ? "ns-mode-danger" : ""}`}
                  title={`${agentLabel(agent)} mode: ${start.description}`}
                />
              ) : null}
              {start?.resume && agent !== "terminal" ? (
                <button
                  type="button"
                  className={`ns-toggle ${resume && !continueBlocked ? "on" : ""}`}
                  aria-pressed={resume && !continueBlocked}
                  aria-label="Continue last"
                  disabled={continueBlocked}
                  title={continueBlocked ? `${agentLabel(agent)} cannot continue a conversation with a starting prompt` : continueHint(agent)}
                  onClick={() => setResume((value) => !value)}
                >
                  <History size={12} /> Continue
                </button>
              ) : null}
              {folder ? (
                <button
                  type="button"
                  className={`ns-toggle ${worktree ? "on" : ""}`}
                  aria-pressed={worktree}
                  aria-label="New worktree"
                  title="New worktree: a git worktree on a new pzza/<name> branch next to the repository, so parallel agents never share a checkout"
                  onClick={() => setWorktree((value) => !value)}
                >
                  <GitBranch size={12} /> Worktree
                </button>
              ) : null}
            </div>
          ) : null}

          {bypass && start ? (
            <p className="ns-warning" role="note">
              <ShieldOff size={11} /> {start.mode} runs every command without asking
            </p>
          ) : null}

          <div className="ns-actions">
            <div className="ns-suggest" aria-label="Quick folders">
              <span className="ns-suggest-label">Recent</span>
              {SHORTCUTS.map((item) => (
                <button
                  key={item.path}
                  type="button"
                  className={`ns-suggest-item ${item.path === folder ? "on" : ""}`}
                  title={item.path}
                  onClick={() => setFolder(item.path)}
                >
                  {item.label}
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {menu && place ? (
        // The list is a portal at the document root in the app (position:
        // fixed under .cselect-backdrop); here it is placed in the window at
        // the point Select computes, beside the panel so the panel's scroll
        // box cannot clip it.
        <div style={{ position: "absolute", right, top, width: 380, height: 0 }}>
          <div
            ref={menuRef}
            className="cselect-menu cselect-menu-list cselect-menu-search"
            style={{ position: "absolute", left: place.left, top: place.top, minWidth: place.minWidth, width: "max-content", ...(room === null ? {} : { "--cselect-room": `${room}px` }) } as CSSProperties}
          >
            <label className="cselect-search">
              <Search size={13} aria-hidden="true" />
              <input
                type="text"
                role="combobox"
                size={1}
                autoFocus={!initialMenu}
                value={query}
                placeholder="Search"
                aria-label="Search Agent to start"
                aria-autocomplete="list"
                aria-expanded="true"
                aria-controls={listId}
                autoComplete="off"
                autoCorrect="off"
                autoCapitalize="off"
                spellCheck={false}
                onChange={(e) => {
                  setQuery(e.target.value);
                  setActive(null);
                }}
              />
            </label>
            <div id={listId} role="listbox" aria-label="Agent to start" className={`cselect-list ${keys ? "cselect-keys" : ""} ${sections.length ? "" : "cselect-list-empty"}`}>
              {sections.map((section, at) =>
                section.group ? (
                  <div key={section.group} role="group" aria-labelledby={`${listId}-group-${at}`} className="cselect-group">
                    <div id={`${listId}-group-${at}`} className="cselect-group-label" aria-hidden="true">
                      {section.group}
                    </div>
                    {section.rows.map(row)}
                  </div>
                ) : (
                  section.rows.map(row)
                ),
              )}
            </div>
            {sections.length ? null : (
              <div className="cselect-empty" role="status">
                No matches
              </div>
            )}
          </div>
        </div>
      ) : null}
    </>
  );
}
